CREATE TABLE IF NOT EXISTS intent_signal_types (id SERIAL PRIMARY KEY, tenant_id INTEGER NOT NULL, key TEXT NOT NULL, label TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'signal', max_points INTEGER NOT NULL CHECK(max_points BETWEEN 0 AND 100), half_life_days INTEGER NOT NULL CHECK(half_life_days > 0), active BOOLEAN NOT NULL DEFAULT TRUE, options JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS intent_signal_types_tenant_key_uq ON intent_signal_types(tenant_id,key);
CREATE TABLE IF NOT EXISTS intent_tiers (id SERIAL PRIMARY KEY, tenant_id INTEGER NOT NULL, key TEXT NOT NULL, label TEXT NOT NULL, min_score INTEGER NOT NULL CHECK(min_score BETWEEN 0 AND 100), color TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS intent_tiers_tenant_key_uq ON intent_tiers(tenant_id,key);
CREATE INDEX IF NOT EXISTS intent_tiers_tenant_score_idx ON intent_tiers(tenant_id,min_score);
CREATE TABLE IF NOT EXISTS intent_signals (id SERIAL PRIMARY KEY, tenant_id INTEGER NOT NULL, client_id INTEGER, signal_type_id INTEGER NOT NULL, account_id INTEGER, contact_id INTEGER, source TEXT NOT NULL, external_id TEXT, row_hash TEXT, summary TEXT, strength INTEGER NOT NULL DEFAULT 50 CHECK(strength BETWEEN 0 AND 100), vertical TEXT, function TEXT, expires_at TIMESTAMPTZ, occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), payload JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS intent_signals_tenant_entity_idx ON intent_signals(tenant_id,account_id,contact_id,occurred_at);
CREATE UNIQUE INDEX IF NOT EXISTS intent_signals_external_uq ON intent_signals(tenant_id,source,external_id) WHERE external_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS intent_signals_row_hash_uq ON intent_signals(tenant_id,source,row_hash) WHERE row_hash IS NOT NULL;
CREATE TABLE IF NOT EXISTS intent_entity_scores (id SERIAL PRIMARY KEY, tenant_id INTEGER NOT NULL, account_id INTEGER, contact_id INTEGER, score INTEGER NOT NULL DEFAULT 0 CHECK(score BETWEEN 0 AND 100), previous_score INTEGER NOT NULL DEFAULT 0, tier TEXT NOT NULL, trend TEXT NOT NULL DEFAULT 'stable', trend_delta INTEGER NOT NULL DEFAULT 0, last_signal_at TIMESTAMPTZ, contributions JSONB NOT NULL DEFAULT '[]', updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK ((account_id IS NOT NULL) <> (contact_id IS NOT NULL)));
CREATE UNIQUE INDEX IF NOT EXISTS intent_entity_scores_account_uq ON intent_entity_scores(tenant_id,account_id) WHERE account_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS intent_entity_scores_contact_uq ON intent_entity_scores(tenant_id,contact_id) WHERE contact_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS intent_entity_scores_tenant_tier_idx ON intent_entity_scores(tenant_id,tier,score);
CREATE TABLE IF NOT EXISTS intent_score_history (id SERIAL PRIMARY KEY, tenant_id INTEGER NOT NULL, entity_score_id INTEGER NOT NULL, score INTEGER NOT NULL, tier TEXT NOT NULL, contributions JSONB NOT NULL DEFAULT '[]', source TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS intent_score_history_tenant_entity_idx ON intent_score_history(tenant_id,entity_score_id,created_at);
CREATE TABLE IF NOT EXISTS intent_recommendations (id SERIAL PRIMARY KEY, tenant_id INTEGER NOT NULL, account_id INTEGER, contact_id INTEGER, tier TEXT NOT NULL, play_type TEXT NOT NULL DEFAULT 'guidance', status TEXT NOT NULL DEFAULT 'pending', title TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', options JSONB NOT NULL DEFAULT '[]', evidence JSONB NOT NULL DEFAULT '{}', note TEXT, error TEXT, generation_status TEXT NOT NULL DEFAULT 'deterministic', generated_at TIMESTAMPTZ, resolved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS intent_recommendations_tenant_status_idx ON intent_recommendations(tenant_id,status,created_at);
CREATE TABLE IF NOT EXISTS intent_recommendation_outcomes (id SERIAL PRIMARY KEY, tenant_id INTEGER NOT NULL, recommendation_id INTEGER NOT NULL, status TEXT NOT NULL, note TEXT, actor_id INTEGER, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS intent_recommendation_outcomes_tenant_rec_idx ON intent_recommendation_outcomes(tenant_id,recommendation_id);
CREATE TABLE IF NOT EXISTS intent_import_runs (id SERIAL PRIMARY KEY, tenant_id INTEGER NOT NULL, client_id INTEGER, kind TEXT NOT NULL, idempotency_key TEXT NOT NULL, file_name TEXT, file_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'completed', total_rows INTEGER NOT NULL DEFAULT 0, inserted_rows INTEGER NOT NULL DEFAULT 0, skipped_rows INTEGER NOT NULL DEFAULT 0, failed_rows INTEGER NOT NULL DEFAULT 0, unmatched_rows INTEGER NOT NULL DEFAULT 0, summary JSONB NOT NULL DEFAULT '{}', errors JSONB NOT NULL DEFAULT '[]', created_by INTEGER, completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS intent_import_runs_tenant_key_uq ON intent_import_runs(tenant_id,idempotency_key);
CREATE UNIQUE INDEX IF NOT EXISTS intent_import_runs_tenant_hash_uq ON intent_import_runs(tenant_id,kind,COALESCE(client_id,0),file_hash);
CREATE TABLE IF NOT EXISTS intent_recompute_queue (id SERIAL PRIMARY KEY, tenant_id INTEGER NOT NULL, account_id INTEGER, contact_id INTEGER, source TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, available_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), claimed_at TIMESTAMPTZ, error TEXT, max_attempts INTEGER NOT NULL DEFAULT 5 CHECK(max_attempts BETWEEN 1 AND 20), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK ((account_id IS NOT NULL) <> (contact_id IS NOT NULL)));
CREATE INDEX IF NOT EXISTS intent_recompute_queue_claim_idx ON intent_recompute_queue(tenant_id,status,available_at);
CREATE INDEX IF NOT EXISTS intent_signals_tenant_type_time_idx ON intent_signals(tenant_id,signal_type_id,occurred_at);
CREATE INDEX IF NOT EXISTS intent_signals_tenant_entity_time_idx ON intent_signals(tenant_id,contact_id,occurred_at);
CREATE INDEX IF NOT EXISTS intent_recommendations_tenant_status_time_idx ON intent_recommendations(tenant_id,status,updated_at);
CREATE UNIQUE INDEX IF NOT EXISTS intent_recommendations_pending_account_uq ON intent_recommendations(tenant_id,account_id) WHERE account_id IS NOT NULL AND status='pending';
CREATE UNIQUE INDEX IF NOT EXISTS intent_recommendations_pending_contact_uq ON intent_recommendations(tenant_id,contact_id) WHERE contact_id IS NOT NULL AND status='pending';
CREATE UNIQUE INDEX IF NOT EXISTS intent_recompute_queue_active_account_uq ON intent_recompute_queue(tenant_id,account_id) WHERE account_id IS NOT NULL AND status IN ('pending','claimed');
CREATE UNIQUE INDEX IF NOT EXISTS intent_recompute_queue_active_contact_uq ON intent_recompute_queue(tenant_id,contact_id) WHERE contact_id IS NOT NULL AND status IN ('pending','claimed');